		"TREE_SITTER_LANGUAGE_VERSION":                maxABI,
		"TREE_SITTER_MIN_COMPATIBLE_LANGUAGE_VERSION": minABI,
	} {
		m := regexp.MustCompile(`(?m)^#define ` + name + ` (\d+)\s*$`).FindSubmatch(api)
